const p = $json.body ?? $json;
const content = String(p.content ?? '').trim();
if (!content) throw new Error('Falta el contenido que debe revisarse');
if (content.length > 20000) throw new Error('El contenido supera 20 000 caracteres');
const rules = [{ type: 'email', regex: /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, replacement: '[EMAIL OCULTO]', weight: 15 }, { type: 'telefono', regex: /(?:\+?51[ -]?)?9\d{8}\b/g, replacement: '[TELÉFONO OCULTO]', weight: 20 }, { type: 'api_key', regex: /sk-(?:proj-)?[A-Za-z0-9_-]{16,}/g, replacement: '[CLAVE API OCULTA]', weight: 50 }, { type: 'tarjeta', regex: /\b(?:\d[ -]*?){13,16}\b/g, replacement: '[NÚMERO FINANCIERO OCULTO]', weight: 40 }, { type: 'documento', regex: /\b(?:DNI|documento)[: ]+\d{8}\b/gi, replacement: '[DOCUMENTO OCULTO]', weight: 35 }];
let redacted = content;
const findings = [];
let score = 0;
for (const rule of rules) { const matches = redacted.match(rule.regex) || []; if (matches.length) { findings.push({ type: rule.type, count: matches.length }); score += rule.weight * matches.length; redacted = redacted.replace(rule.regex, rule.replacement); } }
score = Math.min(100, score);
const risk = score >= 60 ? 'alto' : score >= 25 ? 'medio' : score > 0 ? 'bajo' : 'sin hallazgos';
return [{ json: { ok: true, workflow: 'guardian-privacidad', auditId: `privacy-${Date.now().toString(36)}`, checkedAt: new Date().toISOString(), risk, score, findings, safeToShare: score === 0, redactedContent: redacted, recommendations: score ? ['Usar la versión redactada', 'No publicar secretos ni datos personales', 'Rotar cualquier clave que ya haya sido expuesta'] : ['No se detectaron patrones sensibles comunes', 'Mantener una revisión humana antes de compartir'] } }];

const fs = require('fs');
const file = '/files/nexora-privacy-audit.jsonl';
for (const item of items) { const { redactedContent, ...safeAudit } = item.json; fs.appendFileSync(file, `${JSON.stringify(safeAudit)}\n`, 'utf8'); }
return items.map(item => ({ json: { ...item.json, storedLocally: true, storedSensitiveContent: false, localFile: file, message: 'Revisión de privacidad completada sin guardar el contenido sensible' } }));
